public class Main {
    public static void main(String[] args) {
        //     2
        //    / \
        //   1   3
        Node root = new Node(2);
        root.left = new Node(1);
        root.right = new Node(3);

        System.out.println("Pre-order:  " + preOrder(root));
        System.out.println("In-order:   " + inOrder(root));
        System.out.println("Post-order: " + postOrder(root));
    }

    static String preOrder(Node n) {
        if (n == null) return "";
        return n.value + " " + preOrder(n.left) + preOrder(n.right);
    }

    static String inOrder(Node n) {
        if (n == null) return "";
        return inOrder(n.left) + n.value + " " + inOrder(n.right);
    }

    static String postOrder(Node n) {
        if (n == null) return "";
        return postOrder(n.left) + postOrder(n.right) + n.value + " ";
    }
}

class Node {
    int value;
    Node left;
    Node right;

    Node(int value) {
        this.value = value;
    }
}
